export async function updateProjectRecPart2(projectId, newLayout) {
  const mutation = gql`
    mutation updateProject($id: ID!, $data: ProjectInput!) {
      updateProject(id: $id, data: $data) {
        data {
          id
          attributes {
          title	
tenure		
priceRange	
sizeRange	
totalUnit	
totalStorey
           
          }
        }
      }
    }
  `;



  try {
    const response = await client.mutate({
      mutation,
      variables: {
        id: projectId,
        data: { ...newLayout },  // Spread newLayout to flatten the object
      },
    });
    return response.data.updateProject;
  } catch (error) {
    console.error('Error updating project:', error);
    throw error;
  }
}



