<template>
    <div>
      <h1>Counter: {{ counter }}</h1>
      <button @click="incrementCounter">Increment</button>
      <button @click="decrementCounter">Decrement</button>
    </div>
  </template>
  
  <script>
  import { computed } from 'vue';
 
  
  export default {
    setup() {
      const store = useStore();
  
      // Expose the counter state using a computed property
      const counter = computed(() => store.getters.counter);
      
  
      // Expose actions for incrementing and decrementing
      const incrementCounter = () => store.dispatch('increment');
      const decrementCounter = () => store.dispatch('decrement');
  
      return {
        counter,
        incrementCounter,
        decrementCounter,
      };
    },
  };
  </script>
  