<template>
    <div>
      <h1>Cloudinary File Upload</h1>
      <input type="file" accept="image/*, application/pdf" @change="onFileSelected" />
      <button @click="uploadFile">Upload File</button>
      <div v-if="uploadResult">
        <h3>Uploaded File</h3>
  
        <!-- PDF Thumbnail -->
        <div v-if="uploadResult.format === 'pdf'">
          <img :src="pdfThumbnailUrl" alt="PDF Thumbnail" @click="expandPdf" style="width: 100px; cursor: pointer;" />
        </div>
  
        <!-- Image Preview -->
        <div v-if="uploadResult.format !== 'pdf'">
          <img :src="uploadResult.secure_url" alt="Uploaded Image" style="width: 100px; height: auto;" />
        </div>
  
        <!-- Full PDF Viewer (Hidden initially) -->
        <div v-if="showPdf" style="margin-top: 20px;">
          <iframe :src="uploadResult.secure_url" width="100%" height="600px"></iframe>
          <button @click="closePdf">Close PDF</button>
        </div>
  
        <button @click="removeFile">Remove File</button>
  
        <h3>Optimized URL</h3>
        <a :href="optimizedUrl" target="_blank">{{ optimizedUrl }}</a>
  
        <h3>Auto-Cropped URL</h3>
        <a :href="autoCropUrl" target="_blank">{{ autoCropUrl }}</a>
      </div>
    </div>
  </template>
  
  <script>


import { Cloudinary } from "cloudinary-core";
// Correct import for pdfjs-dist
import { getDocument } from 'pdfjs-dist/webpack';



export default {
  name: "CloudinaryUploader",
  data() {
    return {
      selectedFile: null,
      uploadResult: null,
      optimizedUrl: "",
      autoCropUrl: "",
      showPdf: false,
      pdfThumbnailUrl: "",
    };
  },
  methods: {
    async onFileSelected(event) {
      this.selectedFile = event.target.files[0];
    },

    async uploadFile() {
      if (!this.selectedFile) {
        alert("Please select a file first!");
        return;
      }

      // Initialize Cloudinary client
      const cloudinary = new Cloudinary({
        cloud_name: "alvin-tan",
      });

      try {
        const formData = new FormData();
        formData.append("file", this.selectedFile);
        formData.append("upload_preset", "telco_unifi");

        // Upload the file using Cloudinary API
        const response = await fetch(
          `https://api.cloudinary.com/v1_1/alvin-tan/upload`,
          {
            method: "POST",
            body: formData,
          }
        );

        const result = await response.json();
        this.uploadResult = result;

        // Generate optimized URL (if image)
        if (result.format === "jpg" || result.format === "png") {
          this.optimizedUrl = cloudinary.url(result.public_id, {
            fetch_format: "auto",
            quality: "auto",
          });

          // Generate auto-cropped URL (for images only)
          this.autoCropUrl = cloudinary.url(result.public_id, {
            crop: "fill",
            gravity: "auto",
            width: 500,
            height: 500,
          });
        }

        // Generate PDF thumbnail using PDF.js
        if (result.format === "pdf") {
          this.generatePdfThumbnail(result.secure_url);
        }

        console.log("Upload Result:", result);
      } catch (error) {
        console.error("Upload error:", error);
      }
    },

    // Generate a PDF thumbnail using PDF.js
    async generatePdfThumbnail(pdfUrl) {
      const loadingTask = getDocument(pdfUrl);
      const pdf = await loadingTask.promise;
      const page = await pdf.getPage(1); // First page
      const viewport = page.getViewport({ scale: 0.2 });
      const canvas = document.createElement("canvas");
      const context = canvas.getContext("2d");

      canvas.height = viewport.height;
      canvas.width = viewport.width;

      await page.render({
        canvasContext: context,
        viewport: viewport,
      }).promise;

      this.pdfThumbnailUrl = canvas.toDataURL();
    },

    // Show full PDF
    expandPdf() {
      this.showPdf = true;
    },

    // Close PDF viewer
    closePdf() {
      this.showPdf = false;
    },

    async removeFile() {
      if (!this.uploadResult) {
        alert("No file uploaded to remove!");
        return;
      }

      try {
        const response = await fetch(
          `https://api.cloudinary.com/v1_1/alvin-tan/image/destroy`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              public_id: this.uploadResult.public_id,
              api_key: "534437115195651", // Use your actual Cloudinary API key
              timestamp: Date.now(),
              signature: "YOUR_SIGNATURE", // Replace with a server-side signature
            }),
          }
        );

        const result = await response.json();
        if (result.result === "ok") {
          alert("File removed successfully!");
          this.uploadResult = null;
          this.optimizedUrl = "";
          this.autoCropUrl = "";
          this.pdfThumbnailUrl = "";
        } else {
          alert("Failed to remove file. Please try again.");
        }
        console.log("Remove File Response:", result);
      } catch (error) {
        console.error("Error removing file:", error);
      }
    },
  },
};
</script>
  
  
  <style>
  img {
    display: block;
    margin-top: 10px;
  }
  </style>
  