<template>
  <div v-if="isDeleting" class="loading-indicator">
    <div class="spinner"></div>
    <p>Deleting in progress...</p>
  </div>

  <div class="top-toolbar">
    <div class="button-group">
      <h1>Request Type2: {{ taskMode }}</h1>

      <!-- Dynamic Toolbar Buttons -->
      <button 
        v-for="(btn, index) in buttons" 
        :key="'toolbar-btn-' + index" 
        :class="['toolbar-btn', btn.class]" 
        @click="handleButtonClick(btn)"
      >
        <span class="btn-icon">{{ btn.icon }}</span> {{ btn.label }}
      </button>

      <!-- Vuetify Buttons -->
      <v-btn 
        v-for="(vBtn, index) in vuetifyButtons" 
        :key="'vuetify-btn-' + index" 
        :color="vBtn.color" 
        @click="toggleReport(vBtn.fields)"
      >
        🖹 {{ vBtn.label }}
      </v-btn>
    </div>
  </div>

  <!-- Leads Report -->
  <LeadsReport v-if="showReport" :sort-fields="currentSortFields" />

  <!-- Kanban Board -->
  <ejs-kanban 
    :dataSource="filteredContacts" 
    keyField="stage" 
    :cardSettings="cardSettings" 
    height="100%" 
    width="100%"
    :swimlaneSettings="swimlaneSettings" 
    :enableTooltip="false" 
    :dataBound="OnDataBound" 
    :actionBegin="onActionBegin"
    @cardDoubleClick="onCardDoubleClick" 
    @dialogOpen="preventDefaultDialog" 
    @before-card-save="beforeCardSave"
    @headerClick="onHeaderClick"
  >
    <e-columns>
      <e-column 
        v-for="(column, index) in kanbanColumns" 
        :key="index" 
        :headerText="column.headerText" 
        :keyField="column.keyField"
      ></e-column>
    </e-columns>
  </ejs-kanban>

  <!-- Card Details Dialog -->
  <CardDetailsDialog 
    
    :isSaveDialogVisible="isSaveDialogVisible"
    :selectedCard="selectedCard"
    :taskMode="taskMode"
    @close-dialog="closeDialog"
  />

  <!-- Add Task Dialog -->
  <AddTaskDialog 
    :visible="isAddDialogVisible" 
    :requestType="'task'"
    @close="closeAddDialog" 
    @save="handleAddRecord" 
  />
  
</template>

<script>
import { ref, computed, onMounted, watch } from 'vue';
import { KanbanComponent, ColumnsDirective, ColumnDirective } from '@syncfusion/ej2-vue-kanban';
import { DropDownListComponent } from '@syncfusion/ej2-vue-dropdowns';
import cloudiUpload from '../components/cloudiUpload.vue';
import LeadsReport from './LeadsReport.vue';
import CardDetailsDialog from './cardDetailsDialog.vue';
import AddTaskDialog from './AddTaskDialog.vue';
import { handleAddRecord,loadByProject, updateContact } from "../utils/vgraphql";
import { useKanbanHandlers } from '../composables/useKanbanHandlers';
import { kanbanColumns as configKanbanColumns, toolbarButtons, vuetifyButtons } from '../config/kanbanConfig';

export default {
  name: 'App',
  components: {
    'ejs-kanban': KanbanComponent,
    'e-columns': ColumnsDirective,
    'e-column': ColumnDirective,
    'ejs-dropdownlist': DropDownListComponent,
    CardDetailsDialog,
    AddTaskDialog,
    cloudiUpload,
    LeadsReport
  },
  setup() {
    const isDeleting = ref(false);
    const showReport = ref(false);
    const currentSortFields = ref([]);
    const contacts = ref([]);
    const projectFilter = ref('All');
    const taskMode = ref('buyer');
    const filteredContacts = ref([]);
    const isSaveDialogVisible = ref(false);
    const selectedCard = ref({});
    const isAddDialogVisible = ref(false);
    const showLeadReport = ref(false);
    const ratingFilter = ref(2);
    const dialedDateFilter = ref(null);


    // Computed properties
    const kanbanColumns = computed(() => configKanbanColumns[taskMode.value] || []);

    const filteredContactsComputed = computed(() => {
      return taskMode.value === 'All' 
        ? contacts.value 
        : contacts.value.filter(contact => contact.requestType === taskMode.value);
    });

    // Methods
    const toggleReport = (fields) => {
      showReport.value = !(showReport.value && JSON.stringify(currentSortFields.value) === JSON.stringify(fields));
      currentSortFields.value = fields;
    };

    const filterByType = (type) => {
      taskMode.value = type;
    };

    const handleButtonClick = (btn) => {
      if (btn.action === 'filterByType') {
        filterByType(btn.params);
      } else if (btn.action === 'toggleLeadsReport') {
        toggleLeadsReport();
      } else if (btn.action === 'showAddDialog') {
        showAddDialog();
      }
    };



    const onActionBegin = async (args) => {
      if (args.requestType === 'cardMoved') {
        await updateContact(args.data.id, { stage: args.data.stage });
      }
    };

    const onCardDoubleClick = (args) => {
      args.cancel = true;
      selectedCard.value = args.data;
      isSaveDialogVisible.value = true;
    };

    const closeDialog = async () => {
      isSaveDialogVisible.value = false;
  
      await loadByProject(projectFilter.value, "All",dialedDateFilter,ratingFilter.value, contacts);
 
    };

    

    const showAddDialog = () => {
        isAddDialogVisible.value = true;
    };

    const closeAddDialog = () => {
      isAddDialogVisible.value = false;
    };

    const generateRandomString = () => {
      return Math.random().toString(36).substring(2, 8).toUpperCase();
    };

    const getCardColor = (requestType) => {
      switch (requestType) {
        case "buyer": return "#A779CE";
        case "seller": return "#F7DC6F";
        case "rent": return "#F1948A";
        case "lease": return "#A2D9CE";
        default: return "#D3D3D3";
      }
    };

    const cardSettings = {
      contentField: "interaction",
      headerField: "id",
      template: `
        <div :class="['e-card']" style="background-color: \${requestColor}">
          <div class="card-header">\${stageEmoji}#\${id} 🙋 \${assignee} 🏢\${project} \${coBrokedIcon}</div>
          <div class="card-subheader">\${requestType}  🤵\${name} ☎️\${phoneNumber} <br/>📜: \${remark}</div>
          <div class="card-content truncate">💬\${interaction}</div>
        </div>
      `
    };

    const swimlaneSettings = {
      keyField: "assignee"
    };

    const toggleLeadsReport = () => {
      showLeadReport.value = !showLeadReport.value;
      console.log('Toggled showLeadReport:', showLeadReport.value);
    };

    onMounted(async () => {

      await loadByProject(projectFilter.value, "All", dialedDateFilter,ratingFilter.value, contacts);

    });

    watch(taskMode, (newMode) => {
      filterByType(newMode);
    });

    return {
      isDeleting,
      showReport,
      currentSortFields,
      contacts,
      projectFilter,
      taskMode,
      filteredContacts: filteredContactsComputed,
      isSaveDialogVisible,
      selectedCard,
      isAddDialogVisible,
      kanbanColumns,
      cardSettings,
      swimlaneSettings,
      buttons: toolbarButtons,
      vuetifyButtons,
      toggleReport,
      filterByType,
      loadByProject,
      onActionBegin,
      onCardDoubleClick,
      closeDialog,
      handleAddRecord,
      showAddDialog,
      closeAddDialog,
      getCardColor,
      OnDataBound: useKanbanHandlers().handleDataBound,
      showLeadReport,
      handleButtonClick
    };
  }
};
</script>

<style src="@/assets/css/KanbanStyles.css"></style>